vec3 palette( in float t)
{
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5	);
    vec3 c = vec3(1.0, 0.7, 0.4);
    vec3 d = vec3(0.00, 0.15, 0.20);

    return a + b*cos( 6.283185*(c*t+d) );
}


void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = fragCoord / iResolution.xy * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    float rr = 0.5;
    float speed = 2.5;

    float len = length(uv);
    vec3 finalColor = vec3(0.0);

    vec2 trans = vec2(rr * cos(iTime * speed), rr * sin(iTime * speed));
    uv -= trans;
    float d = length(uv);
    float r = 0.35 * (sin(iTime * 4.0) + 2.0) * exp(-len);
    float sdCircle = d - r;
    float sdRing = abs(sdCircle);
    float ring0 = pow(0.02 / sdRing, 1.2);
    uv += trans;
    finalColor += ring0 * palette(len);

    trans = vec2(rr * cos(-iTime * speed), rr * sin(-iTime * speed));
    uv -= trans;
    d = length(uv);
    r = 0.35 * (cos(iTime * 4.0) + 2.0) * exp(-len);
    sdCircle = d - r;
    sdRing = abs(sdCircle);
    ring0 = pow(0.02 / sdRing, 1.2);
    uv += trans;
    finalColor += ring0 * palette(len);

    trans = vec2(rr * cos(iTime * speed + 1.57), rr * sin(iTime * speed + 1.57));
    uv -= trans;
    d = length(uv);
    r = 0.35 * (cos(iTime * 4.0 + 1.57) + 2.0) * exp(-len);
    sdCircle = d - r;
    sdRing = abs(sdCircle);
    ring0 = pow(0.02 / sdRing, 1.2);
    uv += trans;
    finalColor += ring0 * palette(len);

    trans = vec2(rr * cos(iTime * speed - 1.57), rr * sin(iTime * speed - 1.57));
    uv -= trans;
    d = length(uv);
    r = 0.35 * (sin(iTime * 4.0 - 1.57) + 2.0) * exp(-len);
    sdCircle = d - r;
    sdRing = abs(sdCircle);
    ring0 = pow(0.02 / sdRing, 1.2);
    uv += trans;
    finalColor += ring0 * palette(len);

    float layers = 1.0;

    for (float i = layers; i > 0.0; --i) {
        uv *= 0.9;
        uv = fract(uv);
        uv -= 0.5;

        float rr = 0.2;
        float speed = speed - i;

        vec2 trans = vec2(rr * cos(iTime * speed), rr * sin(iTime * speed));
        uv -= trans;
        float d = length(uv);
        float r = 0.1 * (sin(iTime * 4.0) + 1.5) * exp(-len) * 1.0/i;
        float sdCircle = d - r;
        float sdRing = abs(sdCircle);
        float ring = pow(0.02 / sdRing, 1.2);
        uv += trans;

        trans = vec2(rr * cos(-iTime * speed), rr * sin(-iTime * speed));
        uv -= trans;
        float d2 = length(uv);
        float r2 = 0.1 * (cos(iTime * 4.0) + 1.5) * exp(-len) * 1.0/i;
        float sdCircle2 = d2 - r2;
        float sdRing2 = abs(sdCircle2);
        float ring2 = pow(0.02 / sdRing2, 1.2);
        uv += trans;

        trans = vec2(rr * cos(iTime * speed + 1.57), rr * sin(iTime * speed + 1.57));
        uv -= trans;
        d2 = length(uv);
        r2 = 0.1 * (cos(iTime * 4.0 + 1.57) + 1.5) * exp(-len) * 1.0/i;
        sdCircle2 = d2 - r2;
        sdRing2 = abs(sdCircle2);
        float ring3 = pow(0.02 / sdRing2, 1.2);
        uv += trans;

        trans = vec2(rr * cos(iTime * speed - 1.57), rr * sin(iTime * speed - 1.57));
        uv -= trans;
        d2 = length(uv);
        r2 = 0.1 * (sin(iTime * 4.0 - 1.57) + 1.5) * exp(-len) * 1.0/i;
        sdCircle2 = d2 - r2;
        sdRing2 = abs(sdCircle2);
        float ring4 = pow(0.02 / sdRing2, 1.2);
        uv += trans;



        finalColor += ring * palette(len);
        finalColor += ring2 * palette(len);
        finalColor += ring3 * palette(len);
        finalColor += ring4 * palette(len);
    }

    fragColor = vec4(finalColor, 1.0);
}
